import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BranchBandGit } from '../types'

const git = atom({ plugin: 'branch-band', key: 'git' } as const, null)

// 그리는 중에 git 을 부르면 렌더마다 프로세스가 뜨므로, 브랜치가 바뀔 수 있는 시점에만 다시 읽는다.
async function refresh($: EngineInterface) {
  try {
    const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { timeoutMs: 5000 })
    const head = await $.process.run(['git', 'branch', '--show-current'], { timeoutMs: 5000 })
    const root = top.exitCode === 0 ? top.stdout.trim() : ''
    const branch = head.exitCode === 0 ? head.stdout.trim() : ''
    // 하위 폴더에서 세션을 열어도 레포 이름이 나오도록 cwd 가 아니라 최상위 경로의 마지막 이름을 쓴다.
    const repo = root.split('/').pop() ?? ''
    const next: BranchBandGit | null = repo && branch ? { repo, branch } : null
    await update($, git, () => next)
  } catch {
    await update($, git, () => null)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  })

  // 사용자가 터미널에서 직접 checkout 한 경우도 다음 턴이 끝나면 반영된다.
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await refresh($)
    return result
  })

  // 도구 결과가 브랜치 조회를 기다리지 않도록 기다리지 않고 넘긴다.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const result = await next(e)
    refresh($).catch(() => {})
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const current = await read($, git)

    if (e.props.hasSurvey || current === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box gap={1}>
        {/* 다크 모드에서 antd 라이트 Tag 색은 너무 밝아서 antd 다크 blue Tag 계열로 맞췄다. */}
        {/* 테두리를 두면 band 가 세 줄을 차지하고 Box 에는 radius 가 없어서, 둥근 모서리 없이 배경색으로만 구분한다. */}
        <Box backgroundColor="#1a2f4d" paddingX={1}>
          <Text color="#69b1ff">{current.repo}</Text>
        </Box>
        <Text>{current.branch}</Text>
      </Box>
    )
  })
}

